async (page) => {
  const br = page.context().browser();
  const ctx = await br.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,deviceScaleFactor:3,locale:'en-US',userAgent:'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1'});
  const mp = await ctx.newPage();
  const res = {};
  await mp.goto('http://10.17.1.66:3001/en', {waitUntil:'domcontentloaded'});
  await mp.waitForTimeout(8000);
  // 登录（首页 Sign up 弹层）
  try {
    await mp.getByRole('button', {name:'Sign up'}).first().click();
    await mp.waitForTimeout(2500);
    await mp.locator('input[type=email]').first().fill('450832596@qq.com');
    await mp.locator('input[placeholder=\"Verification Code\"]').first().fill('123456');
    await mp.waitForTimeout(800);
    await mp.evaluate(() => { const bs = Array.from(document.querySelectorAll('button')).filter(b => /log ?in|sign up/i.test(b.textContent.trim()) && b.offsetWidth > 150); if (bs.length) bs[bs.length-1].dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true})); });
    await mp.waitForTimeout(12000);
    res.loggedIn = await mp.evaluate(() => /Credits/.test(document.body.innerText) || /Sign Out/i.test(document.body.innerText));
    res.urlAfterLogin = mp.url();
  } catch (e) { res.loginErr = String(e).slice(0,150); }
  await mp.screenshot({path:'artifacts/2026-09-14_stable_regression_all_archived/evidence/mcp_drift_20260915/mobile_login_after.png'});
  // ID Photo Maker 上传
  try {
    const trigger = mp.getByRole('button', {name:'ID Photo Maker'}).first();
    await trigger.scrollIntoViewIfNeeded();
    await mp.waitForTimeout(500);
    const fc = mp.waitForEvent('filechooser', {timeout:15000});
    await trigger.click();
    const ch = await fc;
    await ch.setFiles(['D:/Test/web-test/test_images/有人脸.JPG']);
    await mp.waitForTimeout(45000);
    res.urlAfterUpload = mp.url();
    res.bodySnippet = (await mp.evaluate(() => document.body.innerText)).slice(0, 400).replace(/\n+/g,' | ');
  } catch (e) { res.idErr = String(e).slice(0,200); res.urlAfterUpload = mp.url(); }
  await mp.screenshot({path:'artifacts/2026-09-14_stable_regression_all_archived/evidence/mcp_drift_20260915/mobile_id_photo.png'});
  await ctx.close();
  return JSON.stringify(res);
}
